def card(c):
 cid,slug,name,group,headline,lead,topics,sample,use,tint=c
 return f'<a class="course-card" data-course-category="{group}" href="/quest/courses/{slug}/" style="--tint:{tint}"><div class="course-cover">{image(cid+"-atlas",name+"の図鑑・"+sample)}</div><div class="course-content"><small>{GROUP[group]}</small><h3>{name}</h3><p>{lead.split("。")[0]}。</p><span class="arrow"><span>教材と図鑑を見る</span><b aria-hidden="true">↗</b></span></div></a>'
def catalog():return '<section class="section white" id="courses"><div class="wrap"><div class="section-head"><div><span class="kicker">FIND YOUR QUEST</span><h2>あなたの「学びたい」が、<br>ここにある。</h2></div><p>中学受験も、資格も、語学も。<br>統合版の12教材を、ひとつのアプリで。<br>掲載画像は、各教材で使われている図鑑です。</p></div><div class="filters" aria-label="教材を絞り込む"><button class="filter" data-filter="all" aria-pressed="true">すべて</button>'+''.join(f'<button class="filter" data-filter="{k}" aria-pressed="false">{v}</button>' for k,v in GROUP.items())+'</div><div class="course-grid">'+''.join(card(c) for c in COURSES)+'</div><p class="course-count fine" data-course-count aria-live="polite">12教材を表示しています</p><p class="fine">教材一覧はiOS公開版の案内を基準にしています。Androidで利用できる教材・機能はストアとアプリでご確認ください。</p></div></section>'
def flow():return '<section class="section white" id="experience"><div class="wrap"><div class="section-head"><div><span class="kicker">LEARN. UNDERSTAND. TRY AGAIN.</span><h2>丸暗記の、その先へ。<br>「わかった」を重ねる学び。</h2></div><p>解いて終わりにしない。<br>図で理解し、クイズで確かめ、まちがいから学ぶ。<br>短い時間でも、ひとつずつ進められます。</p></div><div class="flow">'+''.join(f'<article class="flow-card"><span class="flow-icon" aria-hidden="true">{icon}</span><span class="num">STEP {n}</span><h3>{title}</h3><p>{text}</p></article>' for n,icon,title,text in [('01','▤','図鑑で、つながる。','言葉だけではつかみにくい知識も、イラストと図解で。全体のつながりを見ながら理解を深めます。'),('02','✓','クイズで、たしかめる。','気になる単元を選んで問題に挑戦。答えと解説を確認し、対応問題では音声も活用できます。'),('03','↻','復習で、もう一歩。','まちがえた問題にもう一度挑戦。学習履歴や正答率から、これまで取り組んだ内容を振り返れます。')])+'</div></div></section>'
def kingdom_teaser():return f'<section class="section kingdom" id="kingdom"><div class="wrap kingdom-grid"><div><span class="kicker">YOUR KNOWLEDGE, YOUR KINGDOM</span><h2>学んだぶんだけ、<br><em>自分の王国が育つ。</em></h2><p style="margin-top:22px">今日も、あと一問。<br>その気持ちをつくる、もうひとつの楽しみ。</p><ol class="steps"><li><b class="step-number">1</b><div><strong>問題を解いて、コインを集める。</strong><p>教科をこえた学びが、街づくりの力に。</p></div></li><li><b class="step-number">2</b><div><strong>建物を建てて、街を育てる。</strong><p>家やお店、公園。あなたなら、どんな街に？</p></div></li><li><b class="step-number">3</b><div><strong>ランクが上がると、領地がひらく。</strong><p>港の町、森の里、雪国へ。全16の領地に冒険が広がります。</p></div></li></ol><a class="button" href="/quest/kingdom/">王国の遊び方を見る <span>↗</span></a></div><div><div class="kingdom-shot">{image("kingdom-day-tablet","学習でコインを集め、家やお店を建てた王国マップの実画面")}</div><p class="caption">王国マップの実画面。街の発展状態の一例です。<br>掲載機能はiOS版を基準としています。</p></div></div></section>'
def quiz():return '''<section class="section" id="try"><div class="wrap quiz-box"><div><span class="kicker">A LITTLE DISCOVERY</span><h2>ひとつ「わかった」を、<br>ここで体験。</h2><p style="margin:20px 0">答えがわからなくても大丈夫。<br>理由がわかると、次の一問がおもしろくなります。</p><span class="pill">理科・てこのつり合い</span><p class="fine" style="margin-top:18px">サイト用の体験問題です。アプリ内の学習記録には保存されません。</p></div><div class="quiz-card"><span class="kicker">TRY A QUIZ</span><h3>同じ重さのおもり。<br>右には何個つるすと、つり合う？</h3><svg viewBox="0 0 360 160" role="img" aria-label="支点の左3目盛りに2個のおもり。右3目盛りにつるす個数を考えるてこ"><path d="M25 65H335" stroke="#466550" stroke-width="9" stroke-linecap="round"/><path d="m180 70-24 45h48Z" fill="#e9bd5f"/><path d="M60 65v38M300 65v38" stroke="#466550" stroke-width="3"/><g stroke="#fff" stroke-width="2"><path d="M60 60v10M100 60v10M140 60v10M220 60v10M260 60v10M300 60v10"/></g><rect x="44" y="102" width="32" height="18" rx="4" fill="#e8754f"/><rect x="44" y="123" width="32" height="18" rx="4" fill="#e8754f"/><rect x="280" y="102" width="40" height="39" rx="8" fill="#e3eedb"/><g fill="#193d35" font-family="sans-serif" font-size="15" text-anchor="middle"><text x="118" y="40">3目盛り</text><text x="242" y="40">3目盛り</text><text x="180" y="140">支点</text><text x="300" y="128" font-size="24">?</text></g></svg><div class="quiz-options"><button data-answer="1" aria-pressed="false">1個</button><button data-answer="2" aria-pressed="false">2個</button><button data-answer="3" aria-pressed="false">3個</button><button data-answer="4" aria-pressed="false">4個</button></div><p class="quiz-result" data-quiz-result aria-live="polite">答えを選ぶと、理由がわかります。</p><noscript><p>答えは2個。左右の「重さ × 支点からの距離」を同じにします。</p></noscript></div></div></section>'''
FAQ=[('無料で始められますか？','無料でダウンロードでき、各教材に無料で試せる問題があります。運転免許教材は無料です。追加問題などは対象のProプランで利用できます。無料範囲では広告が表示される場合があります。'),('ひとつのアプリで教材を切り替えられますか？','はい。合格！Questの統合版で教材を選んで学習します。教材ごとに別のアプリをダウンロードする必要はありません。利用できる教材はOS・配信バージョンによって異なる場合があります。'),('中学受験をしない子どもでも使えますか？','理科・社会・国語・算数の基礎の確認や、家庭学習にも使えます。学年だけにとらわれず、興味や理解度に合う単元から始めてください。'),('家族で使えますか？','同じアプリ内でプロフィールを切り替え、学習記録を分けられます。プロフィールの切り替えと、別のApple／Googleアカウントへの購入共有は別の機能です。購入の適用範囲は購入画面とストアの条件をご確認ください。'),('以前の「社会クエスト」を購入しています。','統合版は従来の社会クエストと同じストア掲載先です。以前に購入した対象商品の権利は、購入時と同じストアアカウントで復元できます。ほかの単科アプリの購入が自動で統合版に移るとは限りません。お困りの場合はサポートへご連絡ください。'),('図鑑・音声・王国マップは、どの端末でも同じですか？','図鑑や音声の対象は教材・問題によって異なります。王国マップを含む機能の提供状況はOS・バージョンによって異なる場合があります。初回の教材取得などには通信が必要です。')]
